window.__votdWeek && window.__votdWeek({"week":"2028-06-05","reading":"Alma 5–7","days":[{"d":"2028-06-05","ref":"Alma 5:14","b":"Alma","c":5,"v":14,"he":"וְעַתָּה הִנֵּה שֹׁאֵל אֲנִי מִכֶּם אַחַי בְּנֵי הָעֵדָה הֲנוֹלַדְתֶּם בָּרוּחַ מֵאֱלֹהִים הֲקִבַּלְתֶּם צַלְמוֹ בִּפְנֵיכֶם הַיְדַעְתֶּם הַתְּמוּרָה הַגְּדוֹלָה הַזֹּאת בִּלְבַבְכֶם׃","en":"And now behold, I ask of you, my brethren of the church, have ye spiritually been born of God? Have ye received his image in your countenances? Have ye experienced this mighty change in your hearts?"},{"d":"2028-06-06","ref":"Alma 5:40","b":"Alma","c":5,"v":40,"he":"כִּי אֹמֵר לָכֶם כׇּל־הַטּוֹב מֵאֱלֹהִים הוּא וְכׇל־הָרָע מִן־הַשָּׂטָן הוּא׃","en":"For I say unto you that whatsoever is good cometh from God, and whatsoever is evil cometh from the devil."},{"d":"2028-06-07","ref":"Alma 5:42","b":"Alma","c":5,"v":42,"he":"וְכׇל־הָעֹשֶׂה זֹאת עָלָיו לְקַבֵּל שְׂכָרוֹ מִמֶּנּוּ לָכֵן לִשְׂכָרוֹ יְקַבֵּל מָוֶת בְּדִבְרֵי הַצֶּדֶק בִּהְיוֹתוֹ מֵת לְכׇל־מַעֲשִׂים טוֹבִים׃","en":"And whosoever doeth this must receive his wages of him; therefore, for his wages he receiveth death, as to things pertaining unto righteousness, being dead unto all good works."},{"d":"2028-06-08","ref":"Alma 6:6","b":"Alma","c":6,"v":6,"he":"אַךְ צֻוּוּ בְּנֵי הָאֱלֹהִים לְהִקָּהֵל יַחְדָּו תָּמִיד וּלְהִתְחַבֵּר בְּצוֹם וּבִתְפִלָּה גְדוֹלָה בְּעַד נַפְשׁוֹת אֲשֶׁר לֹא־יָדְעוּ אֶת־הָאֱלֹהִים׃","en":"Nevertheless the children of God were commanded that they should gather themselves together oft, and join in fasting and mighty prayer in behalf of the welfare of the souls of those who knew not God."},{"d":"2028-06-09","ref":"Alma 7:11","b":"Alma","c":7,"v":11,"he":"וְהוּא יֵצֵא וְיִסְבֹּל מַכְאוֹבִים וְצָרוֹת וּמַסּוֹת מִכׇּל־מִין וְזֹאת לְמַעַן יִמָּלֵא הַדָּבָר הָאֹמֵר כִּי יִשָּׂא עָלָיו אֶת־מַכְאוֹבֵי עַמּוֹ וְחׇלְיָם׃","en":"And he shall go forth, suffering pains and afflictions and temptations of every kind; and this that the word might be fulfilled which saith he will take upon him the pains and the sicknesses of his people."},{"d":"2028-06-10","ref":"Alma 7:12","b":"Alma","c":7,"v":12,"he":"וְהוּא יִשָּׂא עָלָיו אֶת־הַמָּוֶת לְמַעַן יְנַתֵּק אֶת־מוֹסְרוֹת הַמָּוֶת הַכּוֹבְלִים אֶת־עַמּוֹ וְיִשָּׂא חֻלְשׁוֹתֵיהֶם לְמַעַן יִמָּלְאוּ מֵעָיו רַחֲמִים כַּבָּשָׂר לְמַעַן יֵדַע כַּבָּשָׂר אֵיךְ לַעְזֹר לְעַמּוֹ כְּחֻלְשׁוֹתֵיהֶם׃","en":"And he will take upon him death, that he may loose the bands of death which bind his people; and he will take upon him their infirmities, that his bowels may be filled with mercy, according to the flesh, that he may know according to the flesh how to succor his people according to their infirmities."},{"d":"2028-06-11","ref":"Alma 7:13","b":"Alma","c":7,"v":13,"he":"וְעַתָּה הָרוּחַ יוֹדֵעַ כׇּל־דָּבָר אַךְ בֶּן־אֱלֹהִים יִסְבֹּל כַּבָּשָׂר לְמַעַן יִשָּׂא חֲטָאֵי עַמּוֹ לְמַעַן יִמְחֶה אֶת־פִּשְׁעֵיהֶם כְּכֹחַ גְּאֻלָּתוֹ וְהִנֵּה זֹאת הָעֵדוּת אֲשֶׁר בִּי׃","en":"Now the Spirit knoweth all things; nevertheless the Son of God suffereth according to the flesh that he might take upon him the sins of his people, that he might blot out their transgressions according to the power of his deliverance; and now behold, this is the testimony which is in me."}]});
